// PreToolUse hook on file edits (docs/claude-code-setup.md §3.2). Refuses edits to
// files that must never change by hand:
// - design/: read-only canvas exports
// - a migration already on main: add a new migration instead
// - src/lib/database.types.ts: generated by `pnpm db:types`
// CI enforces the first two as well (scripts/protected-paths.ts), since this hook
// doesn't see changes made from the shell.

import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { isAbsolute, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = fileURLToPath(new URL("../..", import.meta.url));

/** Whether a repo-relative path exists on main (origin/main, else local main). */
export function isOnMain(rel: string, root = ROOT): boolean {
  for (const ref of ["origin/main", "main"]) {
    try {
      execFileSync("git", ["rev-parse", "--verify", "--quiet", `${ref}^{commit}`], {
        cwd: root,
        stdio: "ignore",
      });
    } catch {
      continue; // ref missing: try the next one
    }
    try {
      execFileSync("git", ["cat-file", "-e", `${ref}:${rel}`], { cwd: root, stdio: "ignore" });
      return true;
    } catch {
      return false;
    }
  }
  return false; // no main to compare with: CI still checks
}

/** Why an edit to this repo-relative path is refused, or null if it's allowed. */
export function protectedReason(rel: string, onMain: (rel: string) => boolean): string | null {
  if (rel === "design" || rel.startsWith("design/")) {
    return "design/ is read-only (CLAUDE.md, Sources of truth). Read the design; don't edit it.";
  }
  if (rel === "src/lib/database.types.ts") {
    return "database.types.ts is generated. Change the schema, then run pnpm db:types.";
  }
  if (/^supabase\/migrations\/[^/]+\.sql$/.test(rel) && onMain(rel)) {
    return (
      `${rel} is already on main, so it may have run on dev and prod. ` +
      "Never edit a merged migration: create a new one with `pnpm exec supabase migration new <name>`."
    );
  }
  return null;
}

type HookInput = { tool_input?: { file_path?: string; notebook_path?: string } };

/** Repo-relative path from the hook input, or null when it's outside the repo. */
export function relativePath(input: HookInput, root = ROOT): string | null {
  const path = input.tool_input?.file_path ?? input.tool_input?.notebook_path;
  if (!path) return null;
  const rel = relative(root, isAbsolute(path) ? path : resolve(root, path))
    .split("\\")
    .join("/");
  return rel.startsWith("../") || rel === ".." || isAbsolute(rel) ? null : rel;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  let input: HookInput = {};
  try {
    input = JSON.parse(readFileSync(0, "utf8")) as HookInput;
  } catch {
    process.exit(0); // not our input: let the normal permission flow decide
  }
  const rel = relativePath(input);
  const reason = rel ? protectedReason(rel, (r) => isOnMain(r)) : null;
  if (reason) {
    console.log(
      JSON.stringify({
        hookSpecificOutput: {
          hookEventName: "PreToolUse",
          permissionDecision: "deny",
          permissionDecisionReason: reason,
        },
      }),
    );
  }
}
